"events.a_futuristic_city_that_is_not":"Uma cidade futurista que ainda não foi construída, demo day em {city}",
"events.a_gigaproject_wants_a_demo_bw":"<b>Um gigaprojeto quer uma demo.</b><br>{bw} por quatro dias em {city}, para exibir uma cidade que ainda é quase só renderização. Veja a aba Negócios.",
"events.a_ship_drifting_without_power":"Um navio à deriva sem energia arrastou a âncora pelos cabos do Mar Vermelho. Todo mundo culpa todo mundo. Os navios de reparo precisam de licença de três governos.",
"events.a_state_owned_isp_accidentally":"Um ISP estatal “sem querer” anunciou seus prefixos por 18 minutos. O comunicado de desculpas estava suspeitamente bem escrito. Muitas redes ainda estão roteando seu tráfego para o vazio.",
"events.baltic_cable_damaged_a_cargo_ship":"<b>Cabo danificado no Báltico</b><br>Um cargueiro arrastou a âncora por 100 km e jura que não percebeu nada. Você não tem links nesses cabos.",
