"events.bgp_hijack_someone_else_is":"<b>BGP hijack</b><br>Outra rede está anunciando seus prefixos. O alcance fica baixo até limparem a bagunça.",
"events.cables_cut_in_the_red_sea":"<b>Cabos cortados no Mar Vermelho</b><br>Um navio arrastou a âncora por vários cabos. Todo mundo culpa todo mundo. Por sorte você não usa esses cabos.",
"events.cables_cut_in_the_red_sea_03e8":"<b>Cabos cortados no Mar Vermelho</b><br>Seus links submarinos fora do ar: {n}, por cerca de {d} dias, enquanto os diplomatas discutem sobre os navios de reparo.",
