"events.faceplant_got_tired_of_korean_usage":"O Faceplant cansou das taxas de uso coreanas e mudou em silêncio os usuários coreanos para os servidores de Hong Kong. As páginas se arrastam para todo mundo em Seoul. O regulador está preparando uma multa.",
"events.faceplant_rerouted_korea_via_hong":"<b>O Faceplant rerroteou a Coreia via Hong Kong.</b><br>Os usuários de Seoul recebem um quinto a menos dele por 20 dias, não importa como você se conecte.",
"events.glitch_is_leaving_korea_the_game":"<b>A Glitch está saindo da Coreia.</b><br>O site de streaming de games diz que as taxas de rede coreanas são “proibitivamente caras” e fecha as portas lá. O tráfego de Seoul dela cai pela metade, para sempre. Os streamers locais já mudaram de casa.",
