"events.new_season_of_stranger_pings_just":"<b>Saiu a nova temporada de “Stranger Pings”!</b><br>A demanda de eyeballs sobe 25% por uma semana. Tem folga?",
"events.optical_control_plane_meltdown_every":"<b>Derretimento do control plane óptico!</b><br>Todas as waves alugadas em {reg} apagaram de uma vez. Sua dark fiber própria está ok. É por isso que as pessoas têm fibra própria.",
"events.ordered_offline_in_city_a_government":"<b>Offline por decreto em {city}</b><br>Um shutdown do governo em dia de prova. Seu POP lá fica apagado por um dia.",
"events.peering_spat_cogentle_de_peered":"<b>Briga de peering!</b><br>A Cogentle cortou o peering com a Goggle por 20 dias. O tráfego da Goggle via transit Cogentle sumiu. Faça peering direto com a Goggle ou use outro upstream.",
"events.regulators_ordered_every_network_in":"As autoridades mandaram todas as redes em {city} desligarem por um dia durante os exames nacionais. Sim, isso acontece de verdade.",
"events.rural_broadband_grant_30k_the":"<b>Verba para banda larga rural: +$30k</b><br>O Ministério dos Tubos gosta do que você está fazendo.",
"events.sanctions_the_republic_of":"<b>Sanções!</b><br>A República do Burocracistão sancionou o fornecedor de parafusos favorito do fabricante do seu router. As peças estão demorando: por 60 dias, crashes de router levam o dobro do tempo para consertar.",
"events.sovereign_internet_drill_moscow":"<b>Treino de internet soberana</b><br>Moscou se desconectou do resto da internet por um dia só para ver o que acontece. Tudo que sai da Rússia fica no escuro até amanhã.",
"events.the_border_got_stricter_cross_border":"<b>A fronteira ficou mais rígida.</b><br>O packet loss transfronteiriço sobe para 35% por 10 dias. Rotas premium quase não são afetadas.",
"events.the_neighbours_have_fallen_out_a":"<b>Os vizinhos brigaram.</b><br>Uma crise diplomática fecha fronteiras e espaço aéreo em volta do Catar. Todos os links entre Doha e Arábia Saudita ou Emirados ficam fora por cerca de {n} dias. Dê a volta longa, por mar.",
"events.trade_war_on_optics_two_governments":"<b>Guerra comercial das ópticas</b><br>Dois governos taxaram os lasers um do outro. Ópticas custam 40% a mais por 90 dias.",
"events.transit_prices_fell_8_they_do":"<b>Os preços de transit caíram 8%.</b><br>Isso acontece todo ano. Ninguém sabe onde fica o fundo do poço.",
