"hot_ports_and_rank.net_transit_lag":"transit {net} · {lag}",
"hot_ports_and_rank.no_pni_with_list":"sem PNI com {list}",
"hot_ports_and_rank.upgrade_the_ix_port_or_add":"Faça upgrade da porta do IX ou adicione um membro ao LAG.",
"hot_ports_and_rank.upgrade_the_router_or_add_a":"Faça upgrade do router ou adicione um segundo na aba Infra.",
"hot_ports_and_rank.you_buy_transit_again":"você volta a comprar transit",
"hot_ports_and_rank.you_cannot_reach_list":"você não alcança {list}",
"hot_ports_and_rank.your_reach_is_p_not_100":"seu alcance é {p}, não 100%",
"hud_and_panels.all_connections_n":"Todas as conexões <small>{n}</small>",
"hud_and_panels.all_systems_green_enjoy_it_while":"Tudo verde. Aproveite enquanto dura.",
"hud_and_panels.auto_fix_in_n_day":{"one":"Se resolve sozinho em {n} dia","other":"Se resolve sozinho em {n} dias"},
"hud_and_panels.blackholing_g":"{g} em blackhole",
"hud_and_panels.customer_level_lv_name":"Nível de cliente {lv}: {name}",
"hud_and_panels.dropping_or_overflowing":"descartando ou transbordando",
"hud_and_panels.every_network_on_the_map_traffic":"Todas as redes do mapa. A fatia de tráfego é quanto do tráfego dos seus usuários vai para elas. Toque numa conexão para ir ao POP dela.",
"hud_and_panels.flowspec_capable_pops":"POPs com Flowspec",
"hud_and_panels.flowspec_drop_rules_live_in_router":"As regras de descarte do Flowspec ficam na TCAM do router, então só routers capazes filtram floods UDP conhecidos (DNS, NTP, CLDAP, SYN) na borda. O Rusty usado não tem nenhuma, os modelos merchant-silicon e whitebox fazem um pouco, os chassis grandes fazem tudo. Faça upgrade do router de um POP na aba Infra.",
"hud_and_panels.g_lost":"{g} perdidos",
"hud_and_panels.happiness_p":"satisfação {p}%",
"hud_and_panels.has_errors_not_running":"tem erros, não está rodando",
"hud_and_panels.incidents_so_far":"Incidentes até agora",
"hud_and_panels.install_auto_te_cost_mo_mo":"Instalar Auto-TE <small>{cost} + {mo}/mês</small>",
"hud_and_panels.large_peering_model_is_on_it":"Large Peering Model está cuidando disso.",
"hud_and_panels.lv_n":"Nv {n}",
"hud_and_panels.n_incident":{"one":"{n} incidente","other":"{n} incidentes"},
"hud_and_panels.n_message_waiting_for_an_answer":{"one":"{n} mensagem esperando resposta.","other":"{n} mensagens esperando resposta."},
"hud_and_panels.n_networks_d_days_left":"{n} redes · faltam {d} dias",
"hud_and_panels.n_new_notification":{"one":"{n} notificação nova","other":"{n} notificações novas"},
"hud_and_panels.n_rules_live":"{n} regras ativas",
