"scenarios.a_path_from_cape_town_to":"Um caminho da Cidade do Cabo ao Cairo, POPs em Lagos e Nairóbi, e 150 Gbps atendidos",
"scenarios.a_path_from_los_angeles_to":"Um caminho de Los Angeles a Sydney com 1.6T em cada trecho, um caminho de Los Angeles a Tóquio e 150 Gbps atendidos",
"scenarios.a_path_from_marseille_to_singapore":"Um caminho de Marselha a Singapura, e 80 Gbps entre a Ásia e o resto da sua rede por 30 dias seguidos",
"scenarios.amsterdam_hosting_capital_of_europe":"Amsterdã, capital europeia do hosting, em plena temporada de botnets. Cada torradeira smart, babá eletrônica e geladeira sem patch da Terra escolheu um lado, e não é o seu. Uma enxurrada a cada poucos dias, cada vez mais na casa dos terabits, enquanto todo o resto continua quebrando também. Você começa com equipamento maior desbloqueado, e vai precisar.",
"scenarios.broadband_in_sydney_melbourne":"Banda larga em Sydney, Melbourne, Brisbane, Adelaide e Perth, e dois cabos diferentes para o exterior",
"scenarios.cape_to_cairo":"Do Cabo ao Cairo",
"scenarios.cape_town_build_a_network_across":"Cidade do Cabo. Construa uma rede pela África: cada fronteira quer sua própria licença, e metade das redes elétricas não está do seu lado.",
"scenarios.cogentle_and_goggle_are_not_speaking":"Cogentle e Goggle não se falam, e desta vez é pra sempre. Compre o transit barato, se tiver coragem.",
"scenarios.deliver_carnaval_in_full":"Entregue o Carnaval completo",
"scenarios.every_cable_through_the_red_sea":"Todos os cabos pelo Mar Vermelho foram cortados, e o salto para o Egito também. Faça Marseille falar com Singapore mesmo assim: contornando a África, por terra ou pelo outro lado do planeta.",
"scenarios.every_ix_is_run_by_de":"Todo IX é operado pela DE-KICKS",
"scenarios.eyeballs_grow_50_faster":"Eyeballs crescem 50% mais rápido",
"scenarios.fibre_to_the_basement":"Fibra até o porão",
"scenarios.gangnam_style_peering":"Gangnam Style Peering",
"scenarios.hold_20_floods_5_of_them":"Aguente 20 enxurradas, 5 delas acima de 1 Tbps, mantendo a cidade atacada em 97% ou mais",
"scenarios.honolulu_in_the_middle_of_the":"Honolulu, no meio do Pacífico. Os cabos entre as Américas, a Ásia e a Austrália são tão longos que uma wave neles carrega só 400G ou 800G. Pare a luz numa ilha, recomece do zero, e cada trecho fica mais curto e mais rápido. Você começa com equipamento 1.6T desbloqueado.",
"scenarios.mid_atlantic_accent":"Sotaque do meio do Atlântico",
"scenarios.only_spatzle_ix":"Só Spätzle-IX",
"scenarios.order_and_progress":"Ordem e Progresso",
"scenarios.ponta_delgada_in_the_azores_halfway":"Ponta Delgada, nos Açores, no meio do Atlântico. Da Flórida à Espanha e de Lisboa a Lagos é um pouco longo demais para uma onda de 1.6T: em linha direta, cada uma leva 1.2T. Pouse nas ilhas no meio, recomece a luz, e cada trecho roda a 1.6T ou mais. Você começa com equipamento de 1.6T desbloqueado.",
"scenarios.pops_in_bogota_lima_santiago_and":"POPs em Bogotá, Lima, Santiago e São Paulo, e 150 Gbps servidos",
"scenarios.ports_on_15_ix_brrr_exchanges":"Portas em 15 exchanges IX.brrr, uma delas em Manaus, e 200 Gbps servidos",
"scenarios.reach_45_of_the_internet_and":"Alcance 45% da internet e atenda 300 Gbps",
"scenarios.red_sea_crisis":"Crise no Mar Vermelho",
"scenarios.rio_from_scratch_carnaval_starts_in":"Rio do zero. O Carnaval começa em 90 dias e quer 400 Gbps por cinco dias seguidos. O mundo inteiro está assistindo.",
"scenarios.sandbox_mode_a_billion_dollars_every":"<b>Modo sandbox</b><br>Um bilhão de dólares, tudo desbloqueado e nada nunca quebra. Construa a internet que você sempre quis.",
"scenarios.sao_paulo_brazil_is_a_continent":"São Paulo. O Brasil é um continente: quarenta exchanges IX.brrr, milhares de provedores e a Amazônia entre você e o norte.",
"scenarios.seoul_the_fastest_hungriest_eyeballs":"Seoul. Os eyeballs mais rápidos e famintos da Terra, transit a quatro vezes o preço, e três incumbentes que te cobram por cada gigabit que você manda.",
"scenarios.shark_season_subsea_cuts_twice_as":"Temporada de tubarão: cortes submarinos duas vezes mais prováveis",
"scenarios.start_in_panama_city_nothing_crosses":"Comece em Panama City. Nada atravessa o Darién Gap por terra, e os Andes atrapalham todo o resto.",
"scenarios.start_in_stuttgart_where_nobody":"Comece em Stuttgart, onde ninguém vende transit. Alcance a internet só com peering, PNIs, caches e sua própria fibra. Nada de transit, em lugar nenhum, nunca.",
"scenarios.start_with_only_100k":"Comece com só $100k",
"scenarios.sydney_2013_the_toilet_paper_group":"Sydney, 2013. O Toilet Paper Group levou a própria fibra até o porão dos prédios, e a rede nacional reclamou de cherry-picking. Sua vez: pule a Nearly Broadband Network, pague a taxa e chegue primeiro.",
